// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address internal initialOwner;

    function setUp() public {
        // Deploy with a non-zero initial owner to observe the difference.
        initialOwner = makeAddr("initialOwner");
        vm.prank(initialOwner);
        c = new C();
        // Initialize with a non-zero owner, because Owner returns zero either way if it's never initialized.
        // We need a scenario where the reference owner is not zero.
        vm.prank(initialOwner);
        c.initialize(1, 1, "test", makeAddr("protocolFeeDest"));
    }

    function testFuzz_property(address randomCaller) public {
        vm.assume(randomCaller != address(0));
        vm.prank(randomCaller);
        address returnedOwner = c.owner();
        // The reference contract must return the original initial owner, not zero.
        assertEq(returnedOwner, initialOwner);
    }
}

