// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        // Admissible domain: any non-zero address that is not the test contract itself
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));

        // Grab the actual owner from the reference (via a static call at the test level, not through the fuzzed caller)
        address actualOwner = c.owner();

        // Now observe c.owner() from the perspective of the fuzzed caller
        vm.prank(caller);
        address returned = c.owner();

        // The returned address must equal the actual owner, regardless of who calls
        assertTrue(returned == actualOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bool actualPaused) public {
        // Set the internal _paused state using the external pause/unpause functions
        // We can only trigger these if we are the owner.
        vm.prank(address(c.owner()));
        if (actualPaused) {
            c.pause();
        } else {
            c.unpause();
        }
        // The rule: paused() must return the actual paused state that was just set.
        // For a reference contract, `c.paused() == actualPaused`.
        // For the buggy contract, `c.paused()` will return `!actualPaused`.
        assertTrue(c.paused() == actualPaused);
    }
}

