pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 dummy) public {
        vm.assume(dummy != 0);
        // After pausing, paused() must return true
        vm.prank(c.owner());
        c.pause();
        bool ok = c.paused();
        assertTrue(ok);
    }
}
